function Page_IllustratedHandbookPartView:OnOpen()
    cs_coroutine.start(function()
        coroutine.yield()
        self:OnInitScrollView()
    end)
    CommonHelper:HButtonSetCallback("BtnGet", self.gameObject, function()
        IllustratedHandbookSubsystem:Get():SendMsg_CollectGift(IllustratedHandbookDataManager:Get().collectLevel)
    end)
    CommonHelper:SetGameObjectActive("BtnGet", self.gameObject, IllustratedHandbookDataManager:Get().collectGift == 1)

    CommonHelper:SetText("###Level", self.gameObject, CommonHelper:GetTempStr_Default(TemplateStringID.IllustratedHandbookLevel, IllustratedHandbookDataManager:Get().collectLevel))

    if IllustratedHandbookDataManager:Get().config.nextval > 0 then
        CommonHelper:SetText("###Exp", self.gameObject, string.format("%s / %s", IllustratedHandbookDataManager:Get().collectVal, IllustratedHandbookDataManager:Get().config.nextval))
    else
        CommonHelper:SetText("###Exp", self.gameObject, CommonHelper:GetTempStr_Default(TemplateStringID.IllustratedHandbookLevelMax))
    end
end

function Page_IllustratedHandbookPartView:OnInitScrollView()
    local DataTable = IllustratedHandbookDataManager:Get():GetIllustratedHandbookDataList(IllustratedHandbookType.Part)
    ---@type table<number,dictcollecthistory_config_cell>
    local HistoryTable = IllustratedHandbookDataManager:Get():GetHistoryConfig()
    local AwardList = IllustratedHandbookDataManager:Get():GetAwardTable()
    CommonHelper:InitMoreRowScrollView(self.ScrollVerticalMoreRow, #AwardList, 1, function(index, item, scrollview)
        local param = Param_ItemArticleParam()
        param.count = AwardList[index + 1].num
        CommonHelper:SetItemComGroup(item, self:GetUIModuleID(), AwardList[index + 1].id, param, function()
            CommonHelper:ShowPartInfoByCfgId(AwardList[index + 1].id, self:GetUIModuleID())
        end)
    end)
    CommonHelper:InitMoreRowScrollView(self.MoreRowScrollView_H, #HistoryTable, 1, function(index, item, scrollview)
        local cell_last = HistoryTable[index]
