        local cell_next = HistoryTable[index + 2]
        local StartBgActive = cell_last == nil or cell_last.year ~= cell.year
        CommonHelper:SetGameObjectActive("StartBg", item, StartBgActive)
        local StartBgEndLineActive = StartBgActive and (cell_next == nil or cell_next.year ~= cell.year)
        CommonHelper:SetGameObjectActive("StartBg/EndLine", item, StartBgEndLineActive)
        local MiddleLineActive = not StartBgActive and cell_next ~= nil and cell_next.year == cell.year
        CommonHelper:SetGameObjectActive("MiddleLine", item, MiddleLineActive)
        local EndLineActive = not StartBgActive and (cell_next == nil or cell_next.year ~= cell.year)
        CommonHelper:SetGameObjectActive("EndLine", item, EndLineActive)

        ---@type dictparts_config_cell
        --local partCfg = CommonHelper:GetTableDataByID(ConfigNames.parts_config,cell.C_ID)
        ---@type dictpartbase_config_cell
        --local partBaseCfg = CommonHelper:GetPartBaseCfg(cfgid)
        CommonHelper:SetText("###name", item, CommonHelper:GetTempStr_Default(cell.partname))
        CommonHelper:SetText("###year", item, cell.year)
        CommonHelper:GetComponentSetUITexture("Icon", item, cell.icon .. ".png", self:GetUIModuleID())
        CommonHelper:HButtonSetCallback("BtnDetail", item, function()
            CommonHelper:ShowHelpView(cell.partdes, cell.partname, nil, true)
        end)
    end)

    CommonHelper:InitMoreRowScrollView(self.MoreRowScrollView_V, #DataTable, 5, function(index, item, scrollview)
        CommonHelper:SetGameObjectActive("UnActiveBg", item, not DataTable[index + 1]:IsActive())
        CommonHelper:SetGameObjectActive("ActiveBg", item, DataTable[index + 1]:IsActive())
        ---@type dictparts_config_cell
        local partCfg = CommonHelper:GetTableDataByID(ConfigNames.parts_config, DataTable[index + 1].partid)
        if partCfg==nil then
            logError("PartCfgKong===>>>",DataTable[index + 1].partid)
            return
        end
        CommonHelper:SetText("UnActiveBg/###name", item, CommonHelper:GetTempStr_Default(partCfg.partname))
        CommonHelper:SetText("ActiveBg/###name", item, CommonHelper:GetTempStr_Default(partCfg.partname))
        CommonHelper:SetText("UnActiveBg/###value", item, CommonHelper:GetTempStr_Default(TemplateStringID.IllustratedHandbookExp, DataTable[index + 1]:GetCollectConfig().collectval))
        CommonHelper:SetText("ActiveBg/###value", item, CommonHelper:GetTempStr_Default(TemplateStringID.IllustratedHandbookExp, DataTable[index + 1]:GetCollectConfig().collectval))

        --CommonHelper:GetComponentSetUITexture("UnActiveBg/icon", item,DataTable[index + 1]:GetCollectConfig().icon, self:GetUIModuleID())
        --CommonHelper:GetComponentSetUITexture("ActiveBg/icon", item,DataTable[index + 1]:GetCollectConfig().icon, self:GetUIModuleID())
        CommonHelper:GetComponentSetUITexture("UnActiveBg/icon", item, DataTable[index + 1]:GetCollectConfig().icon .. ".png", self:GetUIModuleID())
        CommonHelper:GetComponentSetUITexture("ActiveBg/icon", item, DataTable[index + 1]:GetCollectConfig().icon .. ".png", self:GetUIModuleID())
        CommonHelper:HButtonSetCallback("UnActiveBg/BtnDetail", item, function()
            CommonHelper:ShowPartInfoByCfgId(DataTable[index + 1].partid, self:GetUIModuleID())
        end)
        CommonHelper:HButtonSetCallback("ActiveBg/BtnDetail", item, function()
            CommonHelper:ShowPartInfoByCfgId(DataTable[index + 1].partid, self:GetUIModuleID())
